ayer, address _tokenContract, uint256 _quantity ); event DiscountFactorUpdated(uint256 discountFactor); event USDPriceUpdated(address _tokenContract, uint256 _newPrice); error OnlyAccountManagerError(); error TokenNotConfiguredError(); error LockdropEndedError(uint32 end, uint32 block_timestamp); error LockdropInvalidError(); error NFTCostInvalidError(); error USDPriceInvalidError(); error ProposalInProgressError(); error ProposalInvalidContractsError(); error NoProposalError(); error ProposerCannotApproveError(); error ProposalAlreadyApprovedError(); error ProposalAlreadyDisapprovedError(); error ProposalPriceNotMatchedError(); error MaximumLockDurationError(); error ETHValueIncorrectError(); error InvalidMessageValueError(); error InsufficientAllowanceError(); error InsufficientLockAmountError(); error TokenStillLockedError(); error LockManagerInvalidCallError(); error LockManagerRefuseETHError(); error InvalidTokenContractError(); error InvalidLockDurationError(); error LockDurationReducedError(); error SubAccountCannotLockError(); error AccountNotRegisteredError(); error TooManyNFTsError(); } library MunchablesCommonLib { enum Rarity { Primordial, Common, Rare, Epic, Legendary, Mythic, Invalid } enum Realm { Everfrost, Drench, Moltania, Arridia, Verdentis, Invalid } struct NFTImmutableAttributes { Rarity rarity; uint16 species; Realm realm; uint8 generation; uint32 hatchedDate; } struct NFTAttributes { uint256 chonks; uint16 level; uint16 evolution; uint256 lastPettedTime; } struct NFTGameAttribute { GameAttributeType dataType; bytes value; } struct Munchadex { mapping(Realm => uint256) numInRealm; mapping(Rarity => uint256) numInRarity; mapping(bytes32 => uint256) unique; uint256 numUnique; } enum GameAttributeIndex { Strength, Agility, Stamina, Defence, Voracity, Cuteness, Charisma, Trustworthiness, Leadership, Empathy, Intelligence, Cunning, Creativity, Adaptability, Wisdom, IsOriginal, IndexCount } enum GameAttributeType { NotSet, Bool, String, SmallInt, Big