function_name: setLockDuration
code:     function setLockDuration(uint256 _duration) external notPaused {
        if (_duration > configStorage.getUint(StorageKey.MaxLockDuration)) revert MaximumLockDurationError();
        playerSettings[msg.sender].lockDuration = uint32(_duration);
        uint256 configuredTokensLength = configuredTokenContracts.length;
        for (uint256 i; i < configuredTokensLength; i++) {
            address tokenContract = configuredTokenContracts[i];
            if (lockedTokens[msg.sender][tokenContract].quantity > 0) {
                if (
                    uint32(block.timestamp) + uint32(_duration) < lockedTokens[msg.sender][tokenContract].unlockTime
                ) {
                    revert LockDurationReducedError();
                }
                uint32 lastLockTime = lockedTokens[msg.sender][tokenContract]
                    .lastLockTime;
                lockedTokens[msg.sender][tokenContract].unlockTime = lastLockTime + uint32(_duration);
            }
        }
        emit LockDuration(msg.sender, _duration);
    }
vulnerability: Incorrect unlockTime calculation allows early unlock by reducing lock duration
reason: The check uses uint32(block.timestamp) + uint32(_duration) against the current unlockTime, but the new unlockTime is set to lastLockTime + uint32(_duration). Since lastLockTime is always <= block.timestamp, the newly written unlockTime can be less than the current unlockTime. For example, if a user locked at t=100 with duration 1000 (unlockTime=1100), at t=600 they can call setLockDuration(500). The check 600+500 >= 1100 passes, but the new unlockTime becomes 100+500=600, allowing immediate unlock. This defeats the lock mechanism and can be used to bypass lockdrop minimum lock durations after waiting roughly half the lock period.
